package com.bank.zigzag;

import java.util.*;

public class ZigzagChart {

    public List<List<Integer>> zigzag(ChartNode root) {
        List<List<Integer>> result = new ArrayList<>();
        if (root == null) return result;

        Queue<ChartNode> queue = new LinkedList<>();
        queue.offer(root);
        boolean leftToRight = true;
        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            LinkedList<Integer> level = new LinkedList<>();   // O(1) front insert
            for (int i = 0; i < levelSize; i++) {
                ChartNode node = queue.poll();
                if (leftToRight) level.addLast(node.id);      // append
                else level.addFirst(node.id);                 // prepend (reversed)
                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
            result.add(level);
            leftToRight = !leftToRight;                        // flip direction
        }
        return result;
    }
}
