package com.bank.zigzag;

import java.util.logging.Logger;

public class ZigzagDemo {
    private static final Logger log = Logger.getLogger(ZigzagDemo.class.getName());

    public static void main(String[] args) {
        // Tree:        1
        //            /   \
        //           2     3
        //          / \   / \
        //         4   5 6   7
        ChartNode root = new ChartNode(1);
        root.left = new ChartNode(2);
        root.right = new ChartNode(3);
        root.left.left = new ChartNode(4);
        root.left.right = new ChartNode(5);
        root.right.left = new ChartNode(6);
        root.right.right = new ChartNode(7);

        log.info("Zigzag chart: " + new ZigzagChart().zigzag(root));
    }
}
